class Weapon {
  constructor(name, damage) {
    this.name = name;
    this.damage = damage;
  }

  attack() {
    return `${this.name} attacks, dealing ${this.damage} damage.`;
  }
}

class Sword extends Weapon {
  constructor(name, damage, sharpness) {
    super(name, damage);
    this.sharpness = sharpness;
  }

  slash() {
    // Retrieve the base attack message from the parent
    const baseAttackInfo = super.attack();

    // Use regex to extract the damage value from the parent's string output
    const damageMatch = baseAttackInfo.match(/dealing (\d+) damage/);
    let actualDamage = this.damage; // Fallback if parsing fails

    if (damageMatch && damageMatch[1]) {
      actualDamage = parseInt(damageMatch[1], 10);
    }

    // Construct the specific slash message using the extracted damage
    return `The ${this.name} slashes with ${this.sharpness} sharpness, dealing ${actualDamage} damage!`;
  }
}

